def add_symbols(dimension, basis, vectors):
    """Return a canonical tuple of independent bitmasks spanning the union of
    the existing span (basis) and the given vectors, over GF(2) in the given
    dimension. Equal spans in one dimension yield identical tuples regardless
    of insertion order. Tuple length equals the binary rank. Inputs are not
    mutated."""
    # Reduce the existing basis to row-echelon form keyed by the highest set
    # bit (pivot). This is order independent.
    rows = []
    for v in basis:
        x = v
        for p in rows:
            x = min(x, x ^ p)
        if x:
            rows.append(x)
            rows.sort(key=lambda z: z.bit_length(), reverse=True)
    # Add each new vector, eliminating against existing pivots.
    for v in vectors:
        x = v
        for p in rows:
            x = min(x, x ^ p)
        if x:
            rows.append(x)
            rows.sort(key=lambda z: z.bit_length(), reverse=True)
    return tuple(rows)

def contact_batches(tick, contacts, last_use, switch_cooldown, eligible_packets):
    """Yield every legal transmission choice for a single tick as a tuple of
    (contact_id, packet_id, vector) rows, including the empty tuple.

    A contact is usable at this tick when start <= tick < end. A used contact
    must send at least one row and at most rate rows. Used contacts must have
    distinct station, distinct craft and distinct group. A station whose last
    actually-used band differs from a contact's band is blocked while
    tick - last_tick <= switch_cooldown. Only offered symbols for eligible
    packets are selectable; repeated/dependent rows are legal and each consumes
    a rate slot. Ordering within a batch has no semantic effect.
    """
    active = [c for c in contacts if c['start'] <= tick < c['end']]
    # A contact is usable only if its station cooldown permits it.
    usable = []
    for c in active:
        old = last_use.get(c['station'])
        if old is not None and old[0] != c['band'] and tick - old[1] <= switch_cooldown:
            continue
        usable.append(c)
    # Build the list of selectable rows per contact.
    rows_by_contact = {}
    for c in usable:
        rows = []
        for s in c['symbols']:
            if s['packet'] in eligible_packets:
                rows.append((c['id'], s['packet'], s['vector']))
        rows_by_contact[c['id']] = rows

    # Enumerate all subsets of contacts that are mutually exclusive on
    # station/craft/group, then all row multisets within each contact's rate.
    ids = [c['id'] for c in usable]
    n = len(ids)

    def compatible(mask):
        seen = {}
        for i in range(n):
            if mask & (1 << i):
                c = usable[i]
                for field in ('station', 'craft', 'group'):
                    v = c[field]
                    if field in seen and seen[field] != v:
                        return False
                    seen[field] = v
        return True

    def gen_rows(contact_index, remaining, prefix):
        # contact_index: index into usable; remaining: rate slots left.
        if contact_index == n:
            yield tuple(prefix)
            return
        cid = ids[contact_index]
        rows = rows_by_contact[cid]
        # Option: skip this contact.
        yield from gen_rows(contact_index + 1, remaining, prefix)
        # Option: use this contact with 1..rate rows (each row from rows).
        if remaining > 0 and rows:
            rate = usable[contact_index]['rate']
            limit = min(rate, remaining)
            # Enumerate all sequences of length 1..limit from rows.
            def rec(k, acc):
                if k >= 1:
                    yield tuple(acc)
                if k < limit:
                    for r in rows:
                        acc.append(r)
                        yield from rec(k + 1, acc)
                        acc.pop()
            for seq in rec(0, []):
                yield from gen_rows(contact_index + 1, remaining - len(seq), prefix + tuple(seq))

    yield ()
    for mask in range(1, 1 << n):
        if not compatible(mask):
            continue
        # Determine which contacts are used and their total rate capacity.
        used_indices = [i for i in range(n) if mask & (1 << i)]
        total_rate = sum(usable[i]['rate'] for i in used_indices)
        # Generate all row assignments for the used contacts.
        def assign(idx, remaining, prefix):
            if idx == len(used_indices):
                yield tuple(prefix)
                return
            i = used_indices[idx]
            cid = ids[i]
            rows = rows_by_contact[cid]
            rate = usable[i]['rate']
            limit = min(rate, remaining)
            # must use at least one row
            def rec(k, acc):
                if k >= 1:
                    yield tuple(acc)
                if k < limit:
                    for r in rows:
                        acc.append(r)
                        yield from rec(k + 1, acc)
                        acc.pop()
            for seq in rec(0, []):
                yield from assign(idx + 1, remaining - len(seq), prefix + tuple(seq))
        yield from assign(0, total_rate, [])


