def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    q = payload["request"]
    packets = {p["id"]: p for p in q["packets"]}
    contacts = {c["id"]: c for c in q["contacts"]}
    cooldown = q["switch_cooldown"]
    horizon = max(c["end"] for c in q["contacts"])

    # Topological order of packets (requires is a DAG).
    order = []
    seen = set()

    def visit(pid):
        if pid in seen:
            return
        seen.add(pid)
        for r in packets[pid]["requires"]:
            visit(r)
        order.append(pid)

    for pid in packets:
        visit(pid)

    # State: for each packet, its current canonical basis (tuple of bitmasks).
    # We search over the whole horizon with memoization on a compact state.
    # State key: (tick, tuple of bases in topological order, last_use per station).
    # last_use is a tuple of (station, band, tick) sorted by station.

    def state_key(tick, bases, last_use):
        return (tick, tuple(bases[pid] for pid in order),
                tuple(sorted(last_use.items())))

    from functools import lru_cache

    # Precompute eligible packets at a tick given completions.
    def eligible_at(tick, bases, completions):
        elig = set()
        for pid in order:
            p = packets[pid]
            if completions[pid] is not None:
                continue
            if not (p["release"] <= tick < p["deadline"]):
                continue
            if any(completions[r] is None or completions[r] > tick
                   for r in p["requires"]):
                continue
            elig.add(pid)
        return elig

    best = None

    @lru_cache(maxsize=None)
    def search(tick, bases_tuple, last_use_tuple):
        nonlocal best
        bases = {pid: bases_tuple[i] for i, pid in enumerate(order)}
        last_use = dict(last_use_tuple)
        completions = {}
        for pid in order:
            if len(bases[pid]) == packets[pid]["dimension"]:
                # completion time is when it first reached full rank; we track
                # it separately below via a completion map carried in state.
                pass
        # We need completion times in state. Recompute from a carried map.
        # Instead, carry completions in the state key as well.
        return None

    # The above sketch is replaced by a full search below that carries
    # completions explicitly.

    def full_search(tick, bases, completions, last_use):
        nonlocal best
        # Prune: if we can already bound, skip (simple: no pruning).
        elig = eligible_at(tick, bases, completions)
        # Determine which packets are already fully decoded (completion set).
        # If all packets are decoded or tick >= horizon, finalize.
        if tick >= horizon:
            finalize(bases, completions, last_use, [])
            return

        # Enumerate legal batches for this tick.
        for batch in contact_batches(tick, list(q["contacts"]),
                                     last_use, cooldown, elig):
            # Apply the batch: update bases, completions, last_use.
            new_bases = {pid: list(b) for pid, b in bases.items()}
            new_completions = dict(completions)
            new_last_use = dict(last_use)
            used_contacts = set()
            for (cid, pid, vec) in batch:
                used_contacts.add(cid)
                new_bases[pid] = list(add_symbols(
                    packets[pid]["dimension"], tuple(new_bases[pid]), [vec]))
            # Update completions for packets that just reached full rank.
            for pid in order:
                if new_completions[pid] is None and \
                        len(new_bases[pid]) == packets[pid]["dimension"]:
                    new_completions[pid] = tick + 1
            # Update last_use for used contacts.
            for cid in used_contacts:
                c = contacts[cid]
                new_last_use[c["station"]] = (c["band"], tick)
            # Recurse to next tick.
            full_search(tick + 1, new_bases, new_completions, new_last_use)

    def finalize(bases, completions, last_use, transmissions):
        nonlocal best
        # Compute score.
        priority = sum(packets[pid]["priority"]
                       for pid in order if completions[pid] is not None)
        count = sum(1 for pid in order if completions[pid] is not None)
        rank = sum(len(bases[pid]) for pid in order)
        score = (priority, count, rank)
        if best is None or score > best[0]:
            best = (score, bases, completions, last_use, transmissions)

    # We need to record transmissions along the search path. Use a global
    # recorder keyed by state, or carry transmissions. Carry them.
    def full_search(tick, bases, completions, last_use, transmissions):
        nonlocal best
        elig = eligible_at(tick, bases, completions)
        if tick >= horizon:
            finalize(bases, completions, last_use, transmissions)
            return
        for batch in contact_batches(tick, list(q["contacts"]),
                                     last_use, cooldown, elig):
            new_bases = {pid: list(b) for pid, b in bases.items()}
            new_completions = dict(completions)
            new_last_use = dict(last_use)
            used_contacts = set()
            new_transmissions = list(transmissions)
            for (cid, pid, vec) in batch:
                used_contacts.add(cid)
                new_bases[pid] = list(add_symbols(
                    packets[pid]["dimension"], tuple(new_bases[pid]), [vec]))
                new_transmissions.append(
                    {"tick": tick, "contact": cid, "packet": pid, "vector": vec})
            for pid in order:
                if new_completions[pid] is None and \
                        len(new_bases[pid]) == packets[pid]["dimension"]:
                    new_completions[pid] = tick + 1
            for cid in used_contacts:
                c = contacts[cid]
                new_last_use[c["station"]] = (c["band"], tick)
            full_search(tick + 1, new_bases, new_completions, new_last_use,
                        new_transmissions)

