    init_completions = {pid: None for pid in order}
    init_last_use = {}
    full_search(0, init_bases, init_completions, init_last_use, [])

    if best is None:
        # No contacts at all: everything stays undecoded.
        priority = 0
        count = 0
        rank = 0
        return {
            "score": {"priority": priority, "count": count, "rank": rank},
            "packets": [{"id": pid, "rank": 0, "completion": None}
                        for pid in order],
            "contacts": [],
            "transmissions": [],
        }

    score, bases, completions, last_use, transmissions = best
    return {
        "score": {"priority": score[0], "count": score[1], "rank": score[2]},
        "packets": [{"id": pid, "rank": len(bases[pid]),
                     "completion": completions[pid]} for pid in order],
        "contacts": [{"tick": t, "contact": c}
                     for t, c in sorted(
                         {(r["tick"], r["contact"]) for r in transmissions})],
        "transmissions": transmissions,
    }


