from .coding_basis import add_symbols
from .contact_policy import contact_batches


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    q = payload["request"]
    packets = {p["id"]: p for p in q["packets"]}
    contacts = {c["id"]: c for c in q["contacts"]}
    cooldown = q["switch_cooldown"]
    horizon = max(c["end"] for c in q["contacts"])

    order = []
    seen = set()

    def visit(pid):
        if pid in seen:
            return
        seen.add(pid)
        for r in packets[pid]["requires"]:
            visit(r)
        order.append(pid)

    for pid in packets:
        visit(pid)

    def eligible_at(tick, bases, completions):
        elig = set()
        for pid in order:
            p = packets[pid]
            if completions[pid] is not None:
                continue
            if not (p["release"] <= tick < p["deadline"]):
                continue
            if any(completions[r] is None or completions[r] > tick
                   for r in p["requires"]):
                continue
            elig.add(pid)
        return elig

    best = None

    def finalize(bases, completions, transmissions):
        nonlocal best
        priority = sum(packets[pid]["priority"]
                       for pid in order if completions[pid] is not None)
        count = sum(1 for pid in order if completions[pid] is not None)
        rank = sum(len(bases[pid]) for pid in order)
        score = (priority, count, rank)
        if best is None or score > best[0]:
            best = (score, bases, completions, transmissions)

    def full_search(tick, bases, completions, last_use, transmissions):
        nonlocal best
        elig = eligible_at(tick, bases, completions)
        if tick >= horizon:
            finalize(bases, completions, transmissions)
            return
        for batch in contact_batches(tick, list(q["contacts"]),
                                     last_use, cooldown, elig):
            new_bases = {pid: list(b) for pid, b in bases.items()}
            new_completions = dict(completions)
            new_last_use = dict(last_use)
            used_contacts = set()
            new_transmissions = list(transmissions)
            for (cid, pid, vec) in batch:
                used_contacts.add(cid)
                new_bases[pid] = list(add_symbols(
                    packets[pid]["dimension"], tuple(new_bases[pid]), [vec]))
                new_transmissions.append(
                    {"tick": tick, "contact": cid, "packet": pid, "vector": vec})
            for pid in order:
                if new_completions[pid] is None and \
                        len(new_bases[pid]) == packets[pid]["dimension"]:
                    new_completions[pid] = tick + 1
            for cid in used_contacts:
                c = contacts[cid]
                new_last_use[c["station"]] = (c["band"], tick)
            full_search(tick + 1, new_bases, new_completions, new_last_use,
                        new_transmissions)

    init_bases = {pid: () for pid in order}
    init_completions = {pid: None for pid in order}
    full_search(0, init_bases, init_completions, {}, [])

    if best is None:
