def contact_batches(tick, contacts, last_use, switch_cooldown, eligible_packets):
    """Yield every legal transmission choice for a single tick as a tuple of
    (contact_id, packet_id, vector) rows, including the empty tuple.

    A contact is usable at this tick when start <= tick < end. A used contact
    must send at least one row and at most rate rows. Used contacts must have
    distinct station, distinct craft and distinct group. A station whose last
    actually-used band differs from a contact's band is blocked while
    tick - last_tick <= switch_cooldown. Only offered symbols for eligible
    packets are selectable; repeated/dependent rows are legal and each consumes
    a rate slot. Ordering within a batch has no semantic effect.
    """
    active = [c for c in contacts if c['start'] <= tick < c['end']]
    usable = []
    for c in active:
        old = last_use.get(c['station'])
        if old is not None and old[0] != c['band'] and tick - old[1] <= switch_cooldown:
            continue
        usable.append(c)
    rows_by_contact = {}
    for c in usable:
        rows = [(c['id'], s['packet'], s['vector'])
                for s in c['symbols'] if s['packet'] in eligible_packets]
        rows_by_contact[c['id']] = rows

    ids = [c['id'] for c in usable]
    n = len(ids)

    def compatible(mask):
        seen = {}
        for i in range(n):
            if mask & (1 << i):
                c = usable[i]
                for field in ('station', 'craft', 'group'):
                    v = c[field]
                    if field in seen and seen[field] != v:
                        return False
                    seen[field] = v
        return True

    def row_sequences(rows, limit):
        """Yield tuples of 1..limit rows drawn from rows (with repetition)."""
        def rec(k, acc):
            if k >= 1:
                yield tuple(acc)
            if k < limit:
                for r in rows:
                    acc.append(r)
                    yield from rec(k + 1, acc)
                    acc.pop()
        yield from rec(0, [])

    yield ()
    for mask in range(1, 1 << n):
        if not compatible(mask):
            continue
        used_indices = [i for i in range(n) if mask & (1 << i)]
        total_rate = sum(usable[i]['rate'] for i in used_indices)

        def assign(idx, remaining, prefix):
            if idx == len(used_indices):
                yield tuple(prefix)
                return
            i = used_indices[idx]
            rows = rows_by_contact[ids[i]]
            limit = min(usable[i]['rate'], remaining)
            for seq in row_sequences(rows, limit):
                yield from assign(idx + 1, remaining - len(seq),
                                  prefix + list(seq))
        yield from assign(0, total_rate, [])


def _test():
    contacts = [
        {'id': 'c1', 'station': 's', 'craft': 'A', 'band': 'x', 'group': 'g',
         'start': 0, 'end': 2, 'rate': 1,
         'symbols': [{'packet': 'P', 'vector': 1}]},
        {'id': 'c2', 'station': 's', 'craft': 'A', 'band': 'y', 'group': 'g',
         'start': 0, 'end': 2, 'rate': 1,
         'symbols': [{'packet': 'P', 'vector': 2}]},
    ]
    last_use = {'s': ('x', 0)}
    batches = list(contact_batches(1, contacts, last_use, 1, {'P'}))
    assert () in batches
    assert (('c1', 'P', 1),) in batches
    assert all(not any(r[0] == 'c2' for r in b) for b in batches)
    print('contact_policy local check passed')


if __name__ == '__main__':
    _test()

from runtime import build, read

from .coding_basis import add_symbols
from .contact_policy import contact_batches


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    q = payload["request"]
    packets = {p["id"]: p for p in q["packets"]}
    contacts = {c["id"]: c for c in q["contacts"]}
    cooldown = q["switch_cooldown"]
    horizon = max(c["end"] for c in q["contacts"])

    order = []
    seen = set()

    def visit(pid):
        if pid in seen:
            return
        seen.add(pid)
        for r in packets[pid]["requires"]:
            visit(r)
        order.append(pid)

    for pid in packets:
        visit(pid)

    def eligible_at(tick, bases, completions):
        elig = set()
        for pid in order:
            p = packets[pid]
            if completions[pid] is not None:
                continue
            if not (p["release"] <= tick < p["deadline"]):
                continue
            if any(completions[r] is None or completions[r] > tick
                   for r in p["requires"]):
                continue
            elig.add(pid)
        return elig

    best = None

    def finalize(bases, completions, transmissions):
        nonlocal best
        priority = sum(packets[pid]["priority"]
                       for pid in order if completions[pid] is not None)
        count = sum(1 for pid in order if completions[pid] is not None)
        rank = sum(len(bases[pid]) for pid in order)
        score = (priority, count, rank)
        if best is None or score > best[0]:
            best = (score, bases, completions, transmissions)

    def full_search(tick, bases, completions, last_use, transmissions):
        nonlocal best
        elig = eligible_at(tick, bases, completions)
        if tick >= horizon:
            finalize(bases, completions, transmissions)
            return
        for batch in contact_batches(tick, list(q["contacts"]),
                                     last_use, cooldown, elig):
            new_bases = {pid: list(b) for pid, b in bases.items()}
            new_completions = dict(completions)
            new_last_use = dict(last_use)
            used_contacts = set()
            new_transmissions = list(transmissions)
            for (cid, pid, vec) in batch:
                used_contacts.add(cid)
                new_bases[pid] = list(add_symbols(
                    packets[pid]["dimension"], tuple(new_bases[pid]), [vec]))
                new_transmissions.append(
                    {"tick": tick, "contact": cid, "packet": pid, "vector": vec})
            for pid in order:
                if new_completions[pid] is None and \
                        len(new_bases[pid]) == packets[pid]["dimension"]:
                    new_completions[pid] = tick + 1
            for cid in used_contacts:
                c = contacts[cid]
                new_last_use[c["station"]] = (c["band"], tick)
            full_search(tick + 1, new_bases, new_completions, new_last_use,
                        new_transmissions)

    init_bases = {pid: () for pid in order}
    init_completions = {pid: None for pid in order}
    full_search(0, init_bases, init_completions, {}, [])

    if best is None:
        return {
            "score": {"priority": 0, "count": 0, "rank": 0},
            "packets": [{"id": pid, "rank": 0, "completion": None}
                        for pid in order],
            "contacts": [],
            "transmissions": [],
        }

    score, bases, completions, transmissions = best
    return {
        "score": {"priority": score[0], "count": score[1], "rank": score[2]},
        "packets": [{"id": pid, "rank": len(bases[pid]),
                     "completion": completions[pid]} for pid in order],
        "contacts": [{"tick": t, "contact": c}
                     for t, c in sorted(
                         {(r["tick"], r["contact"]) for r in transmissions})],
        "transmissions": transmissions,
    }


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)
